UPGRADE_SQL = r"""
CREATE SCHEMA secureai AUTHORIZATION secureai_owner;

-- ------------------------------------------------------------------ helpers
CREATE FUNCTION secureai.set_updated_at() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, pg_temp AS $$
BEGIN
    NEW.updated_at := now();
    RETURN NEW;
END $$;

-- ------------------------------------------------------------ organizations
CREATE TABLE secureai.organizations (
    id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    name        text NOT NULL CHECK (char_length(name) BETWEEN 1 AND 200),
    slug        text NOT NULL UNIQUE CHECK (slug ~ '^[a-z0-9][a-z0-9-]{1,62}[a-z0-9]$'),
    status      text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'suspended')),
    created_at  timestamptz NOT NULL DEFAULT now(),
    updated_at  timestamptz NOT NULL DEFAULT now()
);

-- -------------------------------------------------------------------- users
-- Global identity. A user is NOT tenant-scoped: one person, many orgs.
CREATE TABLE secureai.users (
    id                 uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    email              text NOT NULL CHECK (
                           email = lower(email)
                           AND char_length(email) BETWEEN 3 AND 320
                           AND email ~ '^[^@\s]+@[^@\s]+$'),
    display_name       text NOT NULL CHECK (char_length(display_name) BETWEEN 1 AND 200),
    status             text NOT NULL DEFAULT 'pending'
                           CHECK (status IN ('pending', 'active', 'disabled', 'locked')),
    email_verified_at  timestamptz,
    created_at         timestamptz NOT NULL DEFAULT now(),
    updated_at         timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT users_email_key UNIQUE (email)
);

-- Credentials are split from the profile so the app role can be granted
-- profile access without ever being able to SELECT a password hash.
CREATE TABLE secureai.user_credentials (
    user_id              uuid PRIMARY KEY REFERENCES secureai.users (id) ON DELETE CASCADE,
    -- Defence in depth: the DB refuses anything that is not an Argon2id PHC string.
    password_hash        text NOT NULL CHECK (password_hash LIKE '$argon2id$v=19$%'),
    password_changed_at  timestamptz NOT NULL DEFAULT now(),
    failed_login_count   integer NOT NULL DEFAULT 0 CHECK (failed_login_count >= 0),
    locked_until         timestamptz,
    updated_at           timestamptz NOT NULL DEFAULT now()
);

-- ------------------------------------------------------- RBAC (global data)
CREATE TABLE secureai.roles (
    id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    key          text NOT NULL UNIQUE CHECK (key ~ '^[a-z][a-z_]{1,48}$'),
    name         text NOT NULL UNIQUE,
    description  text NOT NULL,
    -- Privilege ordering used to stop escalation: you may only assign/manage
    -- roles whose rank is <= your own.
    rank         integer NOT NULL UNIQUE CHECK (rank BETWEEN 0 AND 1000),
    -- false => can never be granted through the application (ops-only).
    assignable   boolean NOT NULL DEFAULT true,
    created_at   timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE secureai.permissions (
    id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    code         text NOT NULL UNIQUE CHECK (code ~ '^[a-z]+\.[a-z_]+$'),
    resource     text GENERATED ALWAYS AS (split_part(code, '.', 1)) STORED,
    action       text GENERATED ALWAYS AS (split_part(code, '.', 2)) STORED,
    description  text NOT NULL,
    created_at   timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE secureai.role_permissions (
    role_id        uuid NOT NULL REFERENCES secureai.roles (id) ON DELETE CASCADE,
    permission_id  uuid NOT NULL REFERENCES secureai.permissions (id) ON DELETE CASCADE,
    created_at     timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (role_id, permission_id)
);
CREATE INDEX role_permissions_permission_idx ON secureai.role_permissions (permission_id);

-- -------------------------------------------------- organization membership
CREATE TABLE secureai.organization_memberships (
    id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    organization_id  uuid NOT NULL REFERENCES secureai.organizations (id) ON DELETE RESTRICT,
    user_id          uuid NOT NULL REFERENCES secureai.users (id) ON DELETE RESTRICT,
    role_id          uuid NOT NULL REFERENCES secureai.roles (id) ON DELETE RESTRICT,
    status           text NOT NULL DEFAULT 'invited'
                         CHECK (status IN ('invited', 'active', 'suspended', 'removed')),
    invited_by       uuid REFERENCES secureai.users (id) ON DELETE SET NULL,
    created_at       timestamptz NOT NULL DEFAULT now(),
    updated_at       timestamptz NOT NULL DEFAULT now(),
    -- Target of every composite FK "(organization_id, user_id)" below:
    -- a record can only reference a user who is a member of the SAME org.
    CONSTRAINT organization_memberships_org_user_key UNIQUE (organization_id, user_id)
);
CREATE INDEX organization_memberships_user_idx ON secureai.organization_memberships (user_id);

CREATE TABLE secureai.user_permission_overrides (
    id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    organization_id  uuid NOT NULL,
    user_id          uuid NOT NULL,
    permission_id    uuid NOT NULL REFERENCES secureai.permissions (id) ON DELETE RESTRICT,
    effect           text NOT NULL CHECK (effect IN ('grant', 'deny')),
    reason           text NOT NULL CHECK (char_length(reason) BETWEEN 3 AND 500),
    created_by       uuid REFERENCES secureai.users (id) ON DELETE SET NULL,
    expires_at       timestamptz,
    created_at       timestamptz NOT NULL DEFAULT now(),
    -- One override per (org, user, permission): a permission is either
    -- explicitly granted or explicitly denied, never both.
    CONSTRAINT user_permission_overrides_unique UNIQUE (organization_id, user_id, permission_id),
    CONSTRAINT user_permission_overrides_expiry CHECK (expires_at IS NULL OR expires_at > created_at),
    FOREIGN KEY (organization_id, user_id)
        REFERENCES secureai.organization_memberships (organization_id, user_id) ON DELETE CASCADE
);

-- ----------------------------------------------------------------- projects
CREATE TABLE secureai.projects (
    id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    organization_id  uuid NOT NULL REFERENCES secureai.organizations (id) ON DELETE RESTRICT,
    owner_id         uuid NOT NULL,
    name             text NOT NULL CHECK (char_length(name) BETWEEN 1 AND 200),
    description      text CHECK (char_length(description) <= 5000),
    status           text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'archived')),
    created_at       timestamptz NOT NULL DEFAULT now(),
    updated_at       timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT projects_org_id_key UNIQUE (organization_id, id),
    FOREIGN KEY (organization_id, owner_id)
        REFERENCES secureai.organization_memberships (organization_id, user_id) ON DELETE RESTRICT
);
CREATE INDEX projects_org_owner_idx ON secureai.projects (organization_id, owner_id);

CREATE TABLE secureai.project_members (
    organization_id  uuid NOT NULL,
    project_id       uuid NOT NULL,
    user_id          uuid NOT NULL,
    project_role     text NOT NULL DEFAULT 'member' CHECK (project_role IN ('lead', 'member')),
    added_by         uuid REFERENCES secureai.users (id) ON DELETE SET NULL,
    created_at       timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (project_id, user_id),
    FOREIGN KEY (organization_id, project_id)
        REFERENCES secureai.projects (organization_id, id) ON DELETE CASCADE,
    FOREIGN KEY (organization_id, user_id)
        REFERENCES secureai.organization_memberships (organization_id, user_id) ON DELETE CASCADE
);
CREATE INDEX project_members_org_user_idx ON secureai.project_members (organization_id, user_id);

-- -------------------------------------------------------------------- tasks
CREATE TABLE secureai.tasks (
    id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    organization_id  uuid NOT NULL,
    project_id       uuid NOT NULL,
    owner_id         uuid NOT NULL,
    assignee_id      uuid,
    title            text NOT NULL CHECK (char_length(title) BETWEEN 1 AND 300),
    description      text CHECK (char_length(description) <= 10000),
    status           text NOT NULL DEFAULT 'todo'
                         CHECK (status IN ('todo', 'in_progress', 'blocked', 'done')),
    priority         text NOT NULL DEFAULT 'medium'
                         CHECK (priority IN ('low', 'medium', 'high', 'urgent')),
    -- Secure default: private (owner + assignee only).
    visibility       text NOT NULL DEFAULT 'private' CHECK (visibility IN ('private', 'project')),
    due_date         date,
    created_at       timestamptz NOT NULL DEFAULT now(),
    updated_at       timestamptz NOT NULL DEFAULT now(),
    -- RESTRICT (not CASCADE): deleting a project must not silently delete
    -- other people's private tasks, because FK cascades bypass RLS.
    FOREIGN KEY (organization_id, project_id)
        REFERENCES secureai.projects (organization_id, id) ON DELETE RESTRICT,
    FOREIGN KEY (organization_id, owner_id)
        REFERENCES secureai.organization_memberships (organization_id, user_id) ON DELETE RESTRICT,
    FOREIGN KEY (organization_id, assignee_id)
        REFERENCES secureai.organization_memberships (organization_id, user_id) ON DELETE RESTRICT
);
CREATE INDEX tasks_org_project_idx  ON secureai.tasks (organization_id, project_id);
CREATE INDEX tasks_org_owner_idx    ON secureai.tasks (organization_id, owner_id);
CREATE INDEX tasks_org_assignee_idx ON secureai.tasks (organization_id, assignee_id)
    WHERE assignee_id IS NOT NULL;

-- ---------------------------------------------------------------- documents
CREATE TABLE secureai.documents (
    id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    organization_id  uuid NOT NULL,
    owner_id         uuid NOT NULL,
    project_id       uuid,
    title            text NOT NULL CHECK (char_length(title) BETWEEN 1 AND 300),
    -- Server-generated object-storage key; never derived from a user filename.
    -- (Length is checked separately: PostgreSQL regex repetition counts max out at 255.)
    storage_key      text NOT NULL UNIQUE CHECK (
                         char_length(storage_key) BETWEEN 8 AND 512
                         AND storage_key ~ '^[A-Za-z0-9/_.-]+$'
                         AND position('..' IN storage_key) = 0),
    content_type     text NOT NULL CHECK (content_type IN (
                         'application/pdf', 'text/plain', 'text/markdown',
                         'application/vnd.openxmlformats-officedocument.wordprocessingml.document')),
    size_bytes       bigint NOT NULL CHECK (size_bytes BETWEEN 0 AND 52428800),
    sha256           bytea NOT NULL CHECK (octet_length(sha256) = 32),
    visibility       text NOT NULL DEFAULT 'private'
                         CHECK (visibility IN ('private', 'project', 'organization')),
    created_at       timestamptz NOT NULL DEFAULT now(),
    updated_at       timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT documents_project_visibility CHECK (visibility <> 'project' OR project_id IS NOT NULL),
    FOREIGN KEY (organization_id, owner_id)
        REFERENCES secureai.organization_memberships (organization_id, user_id) ON DELETE RESTRICT,
    FOREIGN KEY (organization_id, project_id)
        REFERENCES secureai.projects (organization_id, id) ON DELETE RESTRICT
);
CREATE INDEX documents_org_owner_idx   ON secureai.documents (organization_id, owner_id);
CREATE INDEX documents_org_project_idx ON secureai.documents (organization_id, project_id)
    WHERE project_id IS NOT NULL;

-- ------------------------------------------------- conversations / messages
CREATE TABLE secureai.conversations (
    id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    organization_id  uuid NOT NULL,
    user_id          uuid NOT NULL,
    title            text CHECK (char_length(title) <= 300),
    created_at       timestamptz NOT NULL DEFAULT now(),
    updated_at       timestamptz NOT NULL DEFAULT now(),
    -- FK target for messages: pins (org, conversation, owner) together.
    CONSTRAINT conversations_org_id_user_key UNIQUE (organization_id, id, user_id),
    FOREIGN KEY (organization_id, user_id)
        REFERENCES secureai.organization_memberships (organization_id, user_id) ON DELETE RESTRICT
);
CREATE INDEX conversations_org_user_idx ON secureai.conversations (organization_id, user_id);

CREATE TABLE secureai.messages (
    id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    organization_id  uuid NOT NULL,
    conversation_id  uuid NOT NULL,
    -- Denormalised conversation owner. The composite FK below guarantees it
    -- equals conversations.user_id, which lets RLS check ownership without a join.
    user_id          uuid NOT NULL,
    role             text NOT NULL CHECK (role IN ('user', 'assistant', 'system', 'tool')),
    content          text NOT NULL CHECK (char_length(content) <= 100000),
    model            text CHECK (char_length(model) <= 100),
    token_count      integer CHECK (token_count >= 0),
    created_at       timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY (organization_id, conversation_id, user_id)
        REFERENCES secureai.conversations (organization_id, id, user_id) ON DELETE CASCADE
);
CREATE INDEX messages_conversation_idx ON secureai.messages (conversation_id, created_at);

-- ------------------------------------------------------- auth: refresh/reset
CREATE TABLE secureai.refresh_token_sessions (
    id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id         uuid NOT NULL REFERENCES secureai.users (id) ON DELETE CASCADE,
    -- All tokens produced by rotating one login share a family; reuse of any
    -- rotated token revokes the whole family.
    family_id       uuid NOT NULL,
    parent_id       uuid REFERENCES secureai.refresh_token_sessions (id) ON DELETE SET NULL,
    -- HMAC-SHA256(server_pepper, token). The raw token is never stored.
    token_hash      bytea NOT NULL UNIQUE CHECK (octet_length(token_hash) = 32),
    status          text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'rotated', 'revoked')),
    revoked_reason  text CHECK (revoked_reason IN (
                        'logout', 'reuse_detected', 'password_changed', 'admin_revoked',
                        'membership_revoked', 'account_disabled')),
    created_at      timestamptz NOT NULL DEFAULT now(),
    expires_at      timestamptz NOT NULL,
    last_used_at    timestamptz,
    rotated_at      timestamptz,
    revoked_at      timestamptz,
    user_agent      text CHECK (char_length(user_agent) <= 512),
    ip_address      inet,
    CONSTRAINT refresh_sessions_expiry CHECK (expires_at > created_at),
    CONSTRAINT refresh_sessions_revocation CHECK ((status = 'revoked') = (revoked_at IS NOT NULL)),
    CONSTRAINT refresh_sessions_rotation CHECK ((status = 'rotated') <= (rotated_at IS NOT NULL))
);
CREATE INDEX refresh_sessions_user_idx   ON secureai.refresh_token_sessions (user_id);
CREATE INDEX refresh_sessions_family_idx ON secureai.refresh_token_sessions (family_id);

CREATE TABLE secureai.password_reset_tokens (
    id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id       uuid NOT NULL REFERENCES secureai.users (id) ON DELETE CASCADE,
    token_hash    bytea NOT NULL UNIQUE CHECK (octet_length(token_hash) = 32),
    created_at    timestamptz NOT NULL DEFAULT now(),
    expires_at    timestamptz NOT NULL,
    used_at       timestamptz,
    requested_ip  inet,
    CONSTRAINT password_reset_expiry CHECK (
        expires_at > created_at AND expires_at <= created_at + interval '1 hour')
);
CREATE INDEX password_reset_tokens_user_idx ON secureai.password_reset_tokens (user_id);

-- --------------------------------------------------------------- audit logs
-- No foreign keys on purpose: audit records must outlive the rows they describe.
CREATE TABLE secureai.audit_logs (
    id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    occurred_at      timestamptz NOT NULL DEFAULT now(),
    organization_id  uuid,
    actor_user_id    uuid,
    action           text NOT NULL CHECK (action ~ '^[a-z_]+(\.[a-z_]+)+$'),
    resource_type    text CHECK (char_length(resource_type) <= 64),
    resource_id      uuid,
    outcome          text NOT NULL CHECK (outcome IN ('success', 'denied', 'failure', 'error')),
    request_id       text CHECK (char_length(request_id) <= 128),
    ip_address       inet,
    user_agent       text CHECK (char_length(user_agent) <= 512),
    metadata         jsonb NOT NULL DEFAULT '{}'::jsonb
                         CHECK (jsonb_typeof(metadata) = 'object' AND pg_column_size(metadata) <= 16384)
);
CREATE INDEX audit_logs_org_time_idx   ON secureai.audit_logs (organization_id, occurred_at DESC);
CREATE INDEX audit_logs_actor_time_idx ON secureai.audit_logs (actor_user_id, occurred_at DESC);

-- ----------------------------------------------------- updated_at triggers
DO $$
DECLARE t text;
BEGIN
    FOREACH t IN ARRAY ARRAY['organizations', 'users', 'user_credentials', 'organization_memberships',
                             'projects', 'tasks', 'documents', 'conversations']
    LOOP
        EXECUTE format(
            'CREATE TRIGGER %I BEFORE UPDATE ON secureai.%I '
            'FOR EACH ROW EXECUTE FUNCTION secureai.set_updated_at()',
            t || '_set_updated_at', t);
    END LOOP;
END $$;
"""


